package org.synqoria.scheduling;
import java.sql.*;import java.lang.reflect.*;import java.util.*;
public class AppointmentRevisionUpdateTest {public static void main(String[]args)throws Exception{UUID id=UUID.randomUUID();List<Object> params=new ArrayList<>();PreparedStatement ps=(PreparedStatement)Proxy.newProxyInstance(PreparedStatement.class.getClassLoader(),new Class[]{PreparedStatement.class},(p,m,a)->{if(m.getName().startsWith("set"))params.add(a[1]);if(m.getName().equals("executeUpdate"))return 1;return null;});Connection c=(Connection)Proxy.newProxyInstance(Connection.class.getClassLoader(),new Class[]{Connection.class},(p,m,a)->switch(m.getName()){case "getAutoCommit"->false;case "getTransactionIsolation"->Connection.TRANSACTION_SERIALIZABLE;case "prepareStatement"->{String sql=(String)a[0];if(!sql.contains("tenant_id = ?")||!sql.contains("patient_id = ?")||!sql.contains("revision = ?"))throw new AssertionError("missing guard");yield ps;}default->null;});AppointmentRevisionUpdate.requireUpdated(c,new AppointmentTenantContext(id,id,id,id),id,2,"ARRIVED");if(params.size()!=6||!params.get(5).equals(2L))throw new AssertionError("missing revision parameter");boolean denied=false;try{AppointmentRevisionUpdate.requireUpdated(c,new AppointmentTenantContext(id,id,id,id),id,-1,"ARRIVED");}catch(SQLException e){denied=true;}if(!denied)throw new AssertionError("invalid revision allowed");System.out.println("PASS scoped revision update: 5 assertions (mock only)");}}
